//! Checks the Rust watershed against labels recorded from a real QuPath build.
//!
//! The fixture is generated by `parity/java/WatershedFlood.java` via
//! `./parity/record.sh`. Labels are integers carried in `f32`, so the
//! comparison is exact: unlike the measurement tolerances, a watershed label is
//! either the same region or a different one, and "close" is meaningless.

use std::path::Path;

use qupath_watershed::{Connectivity, watershed};

/// One recorded case, parsed from the fixture.
struct Case {
    name: String,
    width: usize,
    conn8: bool,
    min_threshold: f32,
    values: Vec<f32>,
    labels_in: Vec<f32>,
    labels_out: Vec<f32>,
}

/// Minimal extraction for the flat JSON the recorder writes. A dependency on a
/// JSON crate would buy nothing here: the shape is fixed and generated.
fn parse(text: &str) -> Vec<Case> {
    let mut cases = Vec::new();
    for block in text.split("{\n      \"name\"").skip(1) {
        let name = between(block, ": \"", "\"").to_string();
        let width = field(block, "\"width\": ").parse().expect("width");
        let conn8 = field(block, "\"conn8\": ") == "true";
        let raw_threshold = field(block, "\"minThreshold\": ");
        let min_threshold = if raw_threshold.contains("inf") {
            f32::NEG_INFINITY
        } else {
            raw_threshold.parse().expect("minThreshold")
        };
        cases.push(Case {
            name,
            width,
            conn8,
            min_threshold,
            values: array(block, "\"values\": ["),
            labels_in: array(block, "\"labelsIn\": ["),
            labels_out: array(block, "\"labelsOut\": ["),
        });
    }
    assert!(!cases.is_empty(), "fixture parsed to no cases");
    cases
}

fn between<'a>(haystack: &'a str, start: &str, end: &str) -> &'a str {
    let rest = &haystack[haystack.find(start).expect("start") + start.len()..];
    &rest[..rest.find(end).expect("end")]
}

fn field<'a>(block: &'a str, key: &str) -> &'a str {
    let rest = &block[block.find(key).expect(key) + key.len()..];
    rest[..rest.find(['\n', ',']).expect("delimiter")]
        .trim()
        .trim_end_matches(',')
}

fn array(block: &str, key: &str) -> Vec<f32> {
    between(block, key, "]")
        .split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

#[test]
fn matches_qupath_watershed_labels() {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../parity/fixtures/WatershedFlood.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));

    let cases = parse(&text);
    let mut checked = 0;

    for case in &cases {
        let mut labels = case.labels_in.clone();
        watershed(
            &case.values,
            &mut labels,
            case.width,
            case.min_threshold,
            if case.conn8 {
                Connectivity::Eight
            } else {
                Connectivity::Four
            },
        );

        assert_eq!(
            labels, case.labels_out,
            "case {} diverged from QuPath\n  expected: {:?}\n  actual:   {:?}",
            case.name, case.labels_out, labels
        );
        checked += 1;
    }

    // Guards against a fixture that parsed into empty cases and passed
    // vacuously — the failure mode a parity test exists to catch.
    assert_eq!(checked, cases.len());
    assert!(
        checked >= 5,
        "expected at least 5 recorded cases, got {checked}"
    );
}
